import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const primitiveResults = [];
  let disposed = false;

  root.userData.handlers = {};

  const visualSpec = config.intent?.visualSpec ?? {};
  const palette = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const makeGradientMaterial = () => {
    const material = new MeshBasicNodeMaterial();
    const bottom = vec3(0.043, 0.043, 0.063);
    const middle = vec3(0.086, 0.086, 0.114);
    const top = vec3(0.086, 0.086, 0.114);
    const height = smoothstep(0.0, 0.58, uv().y);
    const upper = smoothstep(0.58, 1.0, uv().y);

    material.colorNode = mix(
      mix(bottom, middle, height),
      top,
      upper
    );
    return material;
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = makeGradientMaterial();
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, -1.75, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, backdropMaterial);

  const shadowGeometry = new PlaneGeometry(5.2, 2.65);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: palette.ink,
    transparent: true,
    opacity: 0.5
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0.65, -1.2, -1.65);
  shadow.scale.set(1.05, 0.34, 1);
  root.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const imageGeometry = new PlaneGeometry(4.35, 2.72);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: palette.paper
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.position.set(0.65, -0.65, -0.7);
  root.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const frameGeometry = new PlaneGeometry(4.48, 2.85);
  const frameMaterial = new MeshBasicNodeMaterial({
    color: palette.accent,
    transparent: true,
    opacity: 0.9
  });
  const frame = new Mesh(frameGeometry, frameMaterial);
  frame.position.set(0.65, -0.65, -0.78);
  root.add(frame);
  resources.push(frameGeometry, frameMaterial);

  const accentGeometry = new PlaneGeometry(0.08, 1.12);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: palette.accent
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-2.55, 0.18, -0.45);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.set(-2.35, 0.42, -0.35);
  root.add(textGroup);

  let textOffset = 0;
  for (const item of items) {
    const content = typeof item.text === 'string' ? item.text : '';
    if (!content) continue;

    const role = item.role ?? 'body';
    const fontSize = item.typography?.fontSize ??
      (role === 'hero' ? 68 : role === 'headline' ? 42 : 31);

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize,
      color: palette.paper,
      align: 'left',
      maxWidthPx: role === 'body' ? 620 : 700,
      letterSpacingPx: role === 'caption' ? Math.max(1, fontSize * 0.08) : 0
    });

    textObject.position.set(0, -textOffset, 0);
    textGroup.add(textObject);
    textOffset += role === 'hero' || role === 'headline' ? 0.62 : 0.42;
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  const timeline = gsap.timeline({ paused: false });
  timeline.from(root.scale, {
    x: 0.985,
    y: 0.985,
    z: 0.985,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);
  timeline.from(textGroup.position, {
    x: -2.7,
    duration: 0.7,
    ease: 'power3.out'
  }, 0);
  timeline.from(imagePlane.scale, {
    x: 0.96,
    y: 0.96,
    z: 0.96,
    duration: 0.9,
    ease: 'power4.out'
  }, 0.08);

  for (const primitive of config.cinematicPrimitives ?? []) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    timeline.kill();

    for (const result of primitiveResults) {
      result.timeline?.kill?.();
      result.cleanup?.();
    }

    root.traverse((object) => {
      if (object === root) return;
      object.userData?.cleanup?.();

      if (object.geometry && !resources.includes(object.geometry)) {
        object.geometry.dispose?.();
      }
      if (object.material && !resources.includes(object.material)) {
        if (Array.isArray(object.material)) {
          object.material.forEach((material) => material.dispose?.());
        } else {
          object.material.dispose?.();
        }
      }
    });

    for (const resource of resources) {
      resource.dispose?.();
    }

    root.clear();
  };

  return root;
}
